# ---------- helper stubs (assumed provided) ----------
# The following helper functions are assumed to be available in the execution environment.
# They simply call the corresponding functions from the question description.

def node_by_title(doc, title):
    """Return node matching title, or None."""
    for node in doc["nodes"]:
        if node.get("title") == title:
            return node
    return None

def node_by_id(doc, node_id):
    """Return node matching id, or None."""
    for node in doc["nodes"]:
        if node.get("node_id") == node_id:
            return node
    return None

def children(doc, node):
    """Yield child nodes of the given node."""
    for child_id in node.get("children", []):
        child = node_by_id(doc, child_id)
        if child:
            yield child

def scope_nodes(doc, scope_title):
    """Return iterable of all descendant nodes of a scope node."""
    scope_node = node_by_title(doc, scope_title)
    if not scope_node:
        return []
    return [_ for _ in children(doc, scope_node)]

def table_rows(node):
    """Return list of (row_index, {column: cell_str}) for a table node."""
    rows = []
    for idx, row in enumerate(node.get("table", {}).get("rows", [])):
        cols = {col: cell for col, cell in zip(node["table"]["columns"], row)}
        rows.append((idx, cols))
    return rows

