def parse_dispatch_capacity(text_node):
    """Extract dispatch capacity from a text node if present."""
    text = text_node.get("text", "")
    m = re.search(r"Daily dispatch capacity:\s*([\d,]+)\s*kg", text)
    if m:
        val = int(m.group(1).replace(",", ""))
        return val
    return None

def entities(doc, scope):
    """Return list of entity dicts for the given scope."""
    # scope title e.g. 'Plant 1912, Period 02'
    ents = []

    # Add plant entity
    plant_match = re.match(r"Plant\s+(\d+),", scope)
    if plant_match:
        plant_id = plant_match.group(1)
        ents.append({"id": plant_id, "description": f"Plant {plant_id}"})

    # Add product entities from :Products table
    prod_node = node_by_title(doc, f"{scope}: Products")
    if prod_node and prod_node["kind"] == "table":
        for _, row in table_rows(prod_node):
            prod_code = row.get("product")
            description = f"{prod_code} ({row.get('group')}:{row.get('sub-group')})"
            ents.append({"id": prod_code, "description": description})

    return ents

def recorded_end(doc, scope):
    """Return the last day number in the period or None."""
    ledger_node = node_by_title(doc, f"{scope}: Daily ledger")
    if ledger_node and ledger_node["kind"] == "table":
        max_day = 0
        for _, row in table_rows(ledger_node):
            try:
                day = int(row.get("day"))
                if day > max_day:
                    max_day = day
            except Exception:
                pass
        return float(max_day) if max_day else None
    return None

