                        "id": make_input_id("order", prod, day, "ordered"),
                        "time": day,
                        "kind": "order",
                        "entities": [prod],
                        "fields": {"quantity": ord_qty},
                        "src": [[ledger_node["node_id"], idx, ["ordered"]]]
                    })
            except ValueError:
                pass

    # 3. Order book planned production and orders (future inputs)
    ob_node = node_by_title(doc, f"{scope}: Order book")
    if ob_node and ob_node["kind"] == "table":
        for idx, row in table_rows(ob_node):
            day = float(row.get("day", 0))
            prod = row.get("product")
            # planned production
            try:
                plan_qty = int(row.get("planned production", 0))
                if plan_qty > 0:
                    out.append({
                        "id": make_input_id("planned production", prod, day, "plan"),
                        "time": day,
                        "kind": "planned production",
                        "entities": [prod],
                        "fields": {"quantity": plan_qty},
                        "src": [[ob_node["node_id"], idx, ["planned production"]]]
                    })
            except ValueError:
                pass
            # future orders
            try:
                ord_qty = int(row.get("ordered", 0))
                if ord_qty > 0:
                    out.append({
                        "id": make_input_id("future order", prod, day, "ordered"),
                        "time": day,
                        "kind": "future order",
                        "entities": [prod],
                        "fields": {"quantity": ord_qty},
                        "src": [[ob_node["node_id"], idx, ["ordered"]]]
                    })
            except ValueError:
                pass

    return out

def outcomes(doc, scope):
    out = []

    # 1. Ledger computed quantities: shipped, backordered, stock
    ledger_node = node_by_title(doc, f"{scope}: Daily ledger")
    if ledger_node and ledger_node["kind"] == "table":
        for idx, row in table_rows(ledger_node):
