        for line_index, line in enumerate(events_node.get("lines", [])):
            # extract day number if present
            m = re.search(r"Day\s+(\d+)", line)
            day = float(m.group(1)) if m else None
            out.append({
                "time": day,
                "kind": "event",
                "entities": [],
                "value": None,
                "src": [[events_node["node_id"], line_index]],
                "description": line
            })

    return out

