def parse_dispatch_capacity(text_node):
    """Extract daily dispatch capacity from the main plant text."""
    if not text_node or text_node.get("kind") != "text":
        return None
    txt = text_node.get("text", "")
    m = re.search(r"Daily dispatch capacity:\s*([\d,]+)\s*kg", txt)
